"use client"

import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Label } from "@/components/ui/label"
import { Utensils } from "lucide-react"

interface MacarraoTypeSelectorProps {
  value: "penne" | "parafuso" | "espaguete"
  onChange: (value: "penne" | "parafuso" | "espaguete") => void
}

export function MacarraoTypeSelector({ value, onChange }: MacarraoTypeSelectorProps) {
  const tipos = [
    {
      id: "penne",
      label: "Penne",
      description: "Tubular e inclinado",
      emoji: "🍝"
    },
    {
      id: "parafuso",
      label: "Parafuso",
      description: "Espiral clássico",
      emoji: "🌀"
    },
    {
      id: "espaguete",
      label: "Espaguete",
      description: "Longo e fino",
      emoji: "🍜"
    }
  ]

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h4 className="text-lg font-black text-gray-800 flex items-center gap-2">
          <Utensils className="h-5 w-5 text-yellow-500" />
          Tipo de Macarrão
        </h4>
        <span className="text-[10px] font-bold bg-yellow-500 text-white px-2 py-1 rounded-md uppercase tracking-wider">Obrigatório</span>
      </div>
      
      <RadioGroup value={value} onValueChange={(v) => onChange(v as "penne" | "parafuso" | "espaguete")}>
        <div className="grid grid-cols-3 gap-3">
          {tipos.map((tipo) => (
            <div key={tipo.id}>
              <RadioGroupItem value={tipo.id} id={`macarrao-${tipo.id}`} className="peer sr-only" />
              <Label
                htmlFor={`macarrao-${tipo.id}`}
                className={`flex flex-col items-center justify-center p-4 rounded-2xl border-2 transition-all cursor-pointer text-center ${
                  value === tipo.id
                    ? "border-yellow-500 bg-yellow-100 shadow-md shadow-yellow-200"
                    : "border-gray-100 bg-white hover:border-yellow-300"
                }`}
              >
                <div className="text-3xl mb-2">{tipo.emoji}</div>
                <p className="font-bold text-gray-800 text-sm">{tipo.label}</p>
                <p className="text-[10px] text-gray-500 mt-1">{tipo.description}</p>
              </Label>
            </div>
          ))}
        </div>
      </RadioGroup>
    </div>
  )
}
